Longest Consecutive Sequence in an Array.source:
import java.util.*;

public class Solution {
  public static int solve(int[] a) {
    Set<Integer> set = new HashSet<>();
    for (int x : a) set.add(x);
    int best = 0;
    for (int x : set) {
      if (x != Integer.MIN_VALUE && set.contains(x - 1)) continue;
      int len = 1, y = x;
      while (y != Integer.MAX_VALUE && set.contains(y + 1)) {
        y++;
        len++;
      }
      best = Math.max(best, len);
    }
    return best;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {100, 4, 200, 1, 3, 2}));
  }
}

Longest subarray with sum K.source:
import java.util.*;

public class Solution {
  public static int solve(int[] a, long k) {
    Map<Long, Integer> first = new HashMap<>();
    first.put(0L, -1);
    long sum = 0;
    int best = 0;
    for (int i = 0; i < a.length; i++) {
      sum += a[i];
      Integer at = first.get(sum - k);
      if (at != null) best = Math.max(best, i - at);
      first.putIfAbsent(sum, i);
    }
    return best;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {1, -1, 2, -2, 3}, 3));
  }
}

